contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v) internal {
        vm.assume(true);
        bool reverted;
        try c.SetMinSum(v) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.MinSum() == v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
